#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import {
  MARKETPLACE_CHAT_SECURITY_HEADERS,
  MARKETPLACE_SECURITY_HEADERS,
} from './security-policy.mjs';

const outputUrl = new URL('../ops/tonsofskills-security-headers.caddy', import.meta.url);

export function renderCaddyHeaders(
  headers = MARKETPLACE_SECURITY_HEADERS,
  chatHeaders = MARKETPLACE_CHAT_SECURITY_HEADERS,
) {
  const lines = [
    '# Generated by marketplace/scripts/render-security-headers-caddy.mjs.',
    '# Regenerate with: node marketplace/scripts/render-security-headers-caddy.mjs',
    '# Install inside the tonsofskills.com site block; do not hand-edit.',
    '@tonsofskills_chats path /chats /chats/*',
    `header @tonsofskills_chats Content-Security-Policy ${JSON.stringify(chatHeaders['Content-Security-Policy'])}`,
    '@tonsofskills_non_chats not path /chats /chats/*',
    `header @tonsofskills_non_chats Content-Security-Policy ${JSON.stringify(headers['Content-Security-Policy'])}`,
    'header {',
  ];
  for (const [name, value] of Object.entries(headers)) {
    if (name === 'Content-Security-Policy') continue;
    lines.push(`    ${name} ${JSON.stringify(value)}`);
  }
  lines.push('}', '');
  return lines.join('\n');
}

async function main() {
  const expected = renderCaddyHeaders();
  if (process.argv.includes('--check')) {
    let actual = '';
    try {
      actual = await readFile(outputUrl, 'utf8');
    } catch {
      // The comparison below owns the stable failure message.
    }
    if (actual !== expected) {
      console.error(`security header fragment drift: run node ${fileURLToPath(import.meta.url)}`);
      process.exitCode = 1;
      return;
    }
    console.log('security header fragment: current');
    return;
  }
  await writeFile(outputUrl, expected);
  console.log(`wrote ${fileURLToPath(outputUrl)}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await main();
}
